import java.awt.*;import java.awt.image.*;import java.io.*;import java.util.*;import javax.imageio.ImageIO;import com.koios.client.arpg.PanelCards;import com.koios.client.graphic.*;import com.koios.client.cache.Decompressor;import com.koios.client.stream.StreamLoader;import com.koios.game.arpg.*;import com.koios.game.model.player.Player;import com.koios.game.model.item.Item;import com.koios.network.GamePacket;
public final class PanelCardsCheck {
 static int checks;static void check(boolean b,String text){checks++;if(!b)throw new AssertionError(text);}
 static String payload(Player p,String tab){((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets.clear();PrototypePanel.show(p,tab);for(GamePacket packet:((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets)if(packet.getOpcode()==126){String text=packet.readString();if((packet.readShortA()&65535)==65531)return text;}throw new AssertionError("No actual panel packet");}
 static String[] lines(String payload){return new String(Base64.getDecoder().decode(payload),java.nio.charset.StandardCharsets.UTF_8).split("\n");}
 static BufferedImage draw(com.koios.client.arpg.PrototypePanel panel,TextDrawingArea font){BufferedImage im=new BufferedImage(512,338,BufferedImage.TYPE_INT_RGB);int[] px=((DataBufferInt)im.getRaster().getDataBuffer()).getData();Arrays.fill(px,0x17232C);DrawingArea.initDrawingArea(338,512,px);panel.draw(font,30,130);for(int y=0;y<338;y++)for(int x=0;x<512;x++)if(x<16||x>496||y<16||y>322)check(px[y*512+x]==0x17232C,"Panel rendering stays within panel bounds");return im;}
 static void rectangle(PanelCards cards,int x,int y,int w,int h,String action){for(int[] at:new int[][]{{x,y},{x+w-1,y},{x,y+h-1},{x+w-1,y+h-1},{x+w/2,y+h/2}})check(action.equals(cards.actionAt(at[0],at[1])),"Card inside boundary targets "+action);check(!action.equals(cards.actionAt(x+w,y+h/2))&&!action.equals(cards.actionAt(x+w/2,y+h)),"Card excludes right/bottom boundary "+action);}
 public static void main(String[] args)throws Exception{PrototypeIntegrationCheck.loaded();Player p=PrototypeIntegrationCheck.player("cardaudit",49);p.allowSaveRequests=false;p.setAttribute("tutorial-stage",11);for(int i=0;i<8;i++)p.getInventory().set(i,MapRuns.map(i%3+1,new int[]{0,1,7}[i%3],i%3));PanelCards cards=new PanelCards();String first=payload(p,"maps");check(cards.accept(lines(first)),"Actual server maps selects cards");for(int i=0;i<6;i++)rectangle(cards,28+i%2*232,124+i/2*52,220,44,"open "+i);check(cards.actionAt(30,290)==null,"First page has no Previous target");rectangle(cards,260,286,220,22,"page 1");check(cards.actionAt(252,145)==null&&cards.actionAt(30,279)==null,"Card gutters are inert");PrototypePanel.handle(p,"arpgproto page 1");String second=payload(p,"maps");cards.accept(lines(second));check("open 6".equals(cards.actionAt(30,130))&&"open 7".equals(cards.actionAt(270,130))&&cards.actionAt(30,185)==null,"Real second page has only remaining maps");rectangle(cards,28,286,220,22,"page 0");check(cards.actionAt(270,290)==null,"Last page has no Next target");PrototypePanel.handle(p,"arpgproto page 999");check(p.getAttribute("prototype-page",-1)==1,"Out-of-range page clamps to real last page");PrototypePanel.handle(p,"arpgproto page -99");check(p.getAttribute("prototype-page",-1)==0,"Negative page clamps to first page");check(String.join(" ",lines(first)).contains("NORMAL / No modifiers")&&String.join(" ",lines(first)).contains("MAGIC / 1 modifier")&&String.join(" ",lines(first)).contains("RARE / 3 modifiers"),"Actual map packet includes all rarity/modifier metadata");
 Player supplyOwner=HubServicesCheck.fixture("cardvendor",69);HubServices.ServiceMob vendor=HubServicesCheck.quarter(supplyOwner);HubServicesCheck.approach(supplyOwner,vendor);((PrototypeIntegrationCheck.SessionStub)supplyOwner.getSession()).packets.clear();HubServices.handle(supplyOwner,"hub supplies");String supplyPayload=null;for(GamePacket packet:((PrototypeIntegrationCheck.SessionStub)supplyOwner.getSession()).packets)if(packet.getOpcode()==126){String text=packet.readString();if((packet.readShortA()&65535)==65531)supplyPayload=text;}check(supplyPayload!=null,"Actual service emits quartermaster panel packet");cards.accept(lines(supplyPayload));rectangle(cards,28,124,220,44,"hub buy portals");rectangle(cards,260,124,220,44,"hub buy map");rectangle(cards,28,176,220,44,"hub buy wisdom");check(cards.actionAt(270,290)==null,"Supplies cannot retain map pagination");MapRuns.cleanup(supplyOwner);Player crafter=PrototypeIntegrationCheck.player("cardcrafter",70);crafter.allowSaveRequests=false;crafter.setAttribute("tutorial-stage",11);String emptyCraft=payload(crafter,"craft");check(cards.accept(lines(emptyCraft)),"Zero gem landing uses illustrated crafting cards");for(int row=0;row<3;row++)for(int col=0;col<2;col++)check(cards.actionAt(50+col*232,110+row*52)==null,"Instructional material card is inert");for(int slot=0;slot<8;slot++)crafter.getInventory().set(slot,MapRuns.gem(slot+1,slot%2==1));String gemLanding=payload(crafter,"craft");cards.accept(lines(gemLanding));for(int i=0;i<6;i++)rectangle(cards,28+i%2*232,96+i/2*52,220,44,"select "+i);check(cards.actionAt(30,290)==null&&"page 1".equals(cards.actionAt(270,290)),"Gem first page navigation correct");PrototypePanel.handle(crafter,"arpgproto page 1");String gemLast=payload(crafter,"craft");cards.accept(lines(gemLast));check("select 6".equals(cards.actionAt(30,110))&&"select 7".equals(cards.actionAt(270,110)),"Remaining two gems retain exact inventory targets");check("page 0".equals(cards.actionAt(30,290))&&cards.actionAt(270,290)==null,"Gem last page navigation correct");crafter.getInventory().set(9,AffixCatalog.starter(true));crafter.setAttribute("craft-slot",9);crafter.setAttribute("craft-uuid",crafter.getInventory().get(9).getRoll().getInstanceId());String selectedEquipment=payload(crafter,"craft");cards.accept(lines(selectedEquipment));check("items".equals(cards.actionAt(40,95)),"Selected equipment retains back navigation");for(int row=0;row<3;row++)for(int col=0;col<2;col++)check(cards.actionAt(50+col*232,140+row*52)==null,"Selected equipment material instructions stay inert");PrototypePanel.handle(crafter,"arpgproto items");check(crafter.getAttribute("craft-slot",-1)==-1,"Back action clears equipment selection");Item gem=MapRuns.gem(2,true);p.getInventory().set(10,gem);p.setAttribute("craft-slot",10);p.setAttribute("craft-uuid",gem.getRoll().getInstanceId());String supports=payload(p,"craft");cards.accept(lines(supports));for(int i=0;i<3;i++)rectangle(cards,28+i%2*232,124+i/2*52,220,44,"learn "+(i+2));check(cards.actionAt(30,290)==null,"Maps pagination cannot leak into gem category");Item active=MapRuns.gem(2,false);p.getInventory().set(10,active);p.setAttribute("craft-uuid",active.getRoll().getInstanceId());String skills=payload(p,"craft");cards.accept(lines(skills));check("learn 7".equals(cards.actionAt(30,235)),"Fifth active ability has clickable card");check(!cards.accept(new String[]{"guide","home\tBase"})&&cards.actionAt(30,130)==null,"Switching to noncard category clears old targets");
 try(RandomAccessFile data=new RandomAccessFile("../koios-cache/main_file_cache.dat","r");RandomAccessFile index=new RandomAccessFile("../koios-cache/main_file_cache.idx0","r")){TextDrawingArea font=new TextDrawingArea(false,"p12_full",new StreamLoader(new Decompressor(data,index,1).decompress(1)));PanelCards measured=new PanelCards();measured.accept(lines(first));java.lang.reflect.Field cf=PanelCards.class.getDeclaredField("cards");cf.setAccessible(true);for(Object card:(java.util.List<?>)cf.get(measured)){java.lang.reflect.Field hf=card.getClass().getDeclaredField("h"),wf=card.getClass().getDeclaredField("w"),lf=card.getClass().getDeclaredField("label");hf.setAccessible(true);wf.setAccessible(true);lf.setAccessible(true);java.lang.reflect.Field detailField=card.getClass().getDeclaredField("detail");detailField.setAccessible(true);String metadata=(String)detailField.get(card);if(!metadata.isEmpty())check(font.getTextWidth(metadata)<=wf.getInt(card)-51,"Map metadata fits its actual text column: "+metadata);if(hf.getInt(card)<=30)check(font.getTextWidth((String)lf.get(card))<=wf.getInt(card)-18,"Compact utility text must fit one line: "+lf.get(card));}PanelCards supplyMeasured=new PanelCards();supplyMeasured.accept(lines(supplyPayload));int icons=0;for(Object card:(java.util.List<?>)cf.get(supplyMeasured)){Class<?> ct=card.getClass();java.lang.reflect.Field action=ct.getDeclaredField("action"),icon=ct.getDeclaredField("mapId"),detail=ct.getDeclaredField("detail");action.setAccessible(true);icon.setAccessible(true);detail.setAccessible(true);if(((String)action.get(card)).startsWith("hub buy ")){icons++;check(com.koios.client.arpg.ArtSprites.icon(icon.getInt(card))!=null,"Actual supplied item illustration resolves");check(font.getTextWidth((String)detail.get(card))<=169&&!((String)detail.get(card)).isEmpty(),"Offer price metadata fits actual font column");}}check(icons==3,"All quartermaster offers have item illustrations");BufferedImage sheet=new BufferedImage(1024,1690,BufferedImage.TYPE_INT_RGB);Graphics2D g=sheet.createGraphics();String[] states={first,second,supports,skills,supplyPayload,emptyCraft,gemLanding,gemLast,selectedEquipment};for(int i=0;i<states.length;i++){com.koios.client.arpg.PrototypePanel panel=new com.koios.client.arpg.PrototypePanel();panel.accept(states[i]);g.drawImage(draw(panel,font),i%2*512,i/2*338,null);if(i<2){check(panel.hoverInventorySlot(30,130)==(i==0?0:6),"Map card hover targets exact inventory slot");check(panel.hoverInventorySlot(270,290)==-1,"Pagination cannot expose an inventory tooltip");}check("maps".equals(panel.actionAt(310,30,false)),"Tabs retain category switch target");}g.dispose();ImageIO.write(sheet,"png",new File("build/panel-cards.png"));}System.out.println("Passed "+checks+" actual server card layout, click boundaries, paging, category switch and native bounds checks.");}
}






